-- Instalación nueva: ejecutar completo en Supabase > SQL Editor.
create table public.centres (id uuid primary key default gen_random_uuid(), name text not null, country text not null, search_name text not null, source_url text, updated_at timestamptz not null default now(), unique(name,country));
create index centres_search_name_idx on public.centres(search_name);
create table public.courses (id uuid primary key default gen_random_uuid(), centre_id uuid not null references public.centres(id), course_type text not null check(course_type in ('Curso de 1 día','Curso de 2 días','Curso de 3 días','Curso de 10 días','Curso de 15 días','Curso de 20 días','Curso de 30 días','Curso de 45 días','Curso de 60 días','Satipaṭṭhāna')), start_date date not null, end_date date not null check(end_date >= start_date), created_at timestamptz not null default now(), unique(centre_id,course_type,start_date,end_date));
create table public.viajes (id bigint generated by default as identity primary key, course_id uuid not null references public.courses(id), nombre text not null check(char_length(nombre) between 1 and 80), apellidos text check(char_length(apellidos)<=120), ciudad_salida text check(char_length(ciudad_salida)<=100), aeropuerto text check(char_length(aeropuerto)<=120), llegada_centro date, comentarios text check(char_length(comentarios)<=800), consentimiento boolean not null default false, telefono text check(char_length(telefono)<=40), email text check(char_length(email)<=254), created_at timestamptz not null default now(), constraint contact_requires_consent check(consentimiento or (telefono is null and email is null)));
create index viajes_course_idx on public.viajes(course_id);
alter table public.centres enable row level security; alter table public.courses enable row level security; alter table public.viajes enable row level security;
create policy "Centres visibles" on public.centres for select using (true); create policy "Cursos visibles" on public.courses for select using (true); create policy "Viajes visibles" on public.viajes for select using (true); create policy "Cursos públicos" on public.courses for insert with check (true); create policy "Viajes públicos" on public.viajes for insert with check (true);
